# ! [doc = " # Runtime version checking ABI for other compilers."] # ! [doc = ""] # ! [doc = " The symbols in this file are useful for us to expose to allow linking code written in the"] # ! [doc = " following languages when using their version checking functionality:"] # ! [doc = " - Clang's `__builtin_available` macro."] # ! [doc = " - Objective-C's `@available`."] # ! [doc = " - Swift's `#available`,"] # ! [doc = ""] # ! [doc = " Without Rust exposing these symbols, the user would encounter a linker error when linking to"] # ! [doc = " C/Objective-C/Swift libraries using these features."] # ! [doc = ""] # ! [doc = " The presence of these symbols is mostly considered a quality-of-implementation detail, and"] # ! [doc = " should not be relied upon to be available. The intended effect is that linking with code built"] # ! [doc = " with Clang's `__builtin_available` (or similar) will continue to work. For example, we may"] # ! [doc = " decide to remove `__isOSVersionAtLeast` if support for Clang 11 (Xcode 11) is dropped."] # ! [doc = ""] # ! [doc = " ## Background"] # ! [doc = ""] # ! [doc = " The original discussion of this feature can be found at:"] # ! [doc = " - <https://lists.llvm.org/pipermail/cfe-dev/2016-July/049851.html>"] # ! [doc = " - <https://reviews.llvm.org/D27827>"] # ! [doc = " - <https://reviews.llvm.org/D30136>"] # ! [doc = ""] # ! [doc = " And the upstream implementation of these can be found in `compiler-rt`:"] # ! [doc = " <https://github.com/llvm/llvm-project/blob/llvmorg-20.1.0/compiler-rt/lib/builtins/os_version_check.c>"] # ! [doc = ""] # ! [doc = " Ideally, these symbols should probably have been a part of Apple's `libSystem.dylib`, both"] # ! [doc = " because their implementation is quite complex, using allocation, environment variables, file"] # ! [doc = " access and dynamic library loading (and emitting all of this into every binary)."] # ! [doc = ""] # ! [doc = " The reason why Apple chose to not do that originally is lost to the sands of time, but a good"] # ! [doc = " reason would be that implementing it as part of `compiler-rt` allowed them to back-deploy this"] # ! [doc = " to older OSes immediately."] # ! [doc = ""] # ! [doc = " In Rust's case, while we may provide a feature similar to `@available` in the future, we will"] # ! [doc = " probably do so as a macro exposed by `std` (and not as a compiler builtin). So implementing this"] # ! [doc = " in `std` makes sense, since then we can implement it using `std` utilities, and we can avoid"] # ! [doc = " having `compiler-builtins` depend on `libSystem.dylib`."] # ! [doc = ""] # ! [doc = " This does mean that users that attempt to link C/Objective-C/Swift code _and_ use `#![no_std]`"] # ! [doc = " in all their crates may get a linker error because these symbols are missing. Using `no_std` is"] # ! [doc = " quite uncommon on Apple systems though, so it's probably fine to not support this use-case."] # ! [doc = ""] # ! [doc = " The workaround would be to link `libclang_rt.osx.a` or otherwise use Clang's `compiler-rt`."] # ! [doc = ""] # ! [doc = " See also discussion in <https://github.com/rust-lang/compiler-builtins/pull/794>."] # ! [doc = ""] # ! [doc = " ## Implementation details"] # ! [doc = ""] # ! [doc = " NOTE: Since macOS 10.15, `libSystem.dylib` _has_ actually provided the undocumented"] # ! [doc = " `_availability_version_check` via `libxpc` for doing the version lookup (zippered, which is why"] # ! [doc = " it requires a platform parameter to differentiate between macOS and Mac Catalyst), though its"] # ! [doc = " usage may be a bit dangerous, see:"] # ! [doc = " - <https://reviews.llvm.org/D150397>"] # ! [doc = " - <https://github.com/llvm/llvm-project/issues/64227>"] # ! [doc = ""] # ! [doc = " Besides, we'd need to implement the version lookup via PList to support older versions anyhow,"] # ! [doc = " so we might as well use that everywhere (since it can also be optimized more after inlining)."] # ! [allow (non_snake_case)] use split_decls_genesis :: ourprelude :: * ; use super :: { current_version , pack_i32_os_version } ; #[doc = " Whether the current platform's OS version is higher than or equal to the given version."] #[doc = ""] #[doc = " The first argument is the _base_ Mach-O platform (i.e. `PLATFORM_MACOS`, `PLATFORM_IOS`, etc.,"] #[doc = " but not `PLATFORM_IOSSIMULATOR` or `PLATFORM_MACCATALYST`) of the invoking binary."] #[doc = ""] #[doc = " Arguments are specified statically by Clang. Inlining with LTO should allow the versions to be"] #[doc = " combined into a single `u32`, which should make comparisons faster, and should make the"] #[doc = " `BASE_TARGET_PLATFORM` check a no-op."] #[rustc_std_internal_symbol] #[linkage = "weak"] pub (super) extern "C" fn __isPlatformVersionAtLeast (platform : i32 , major : i32 , minor : i32 , subminor : i32 ,) -> i32 { let version = pack_i32_os_version (major , minor , subminor) ; const BASE_TARGET_PLATFORM : i32 = if cfg ! (target_os = "macos") { 1 } else if cfg ! (target_os = "ios") { 2 } else if cfg ! (target_os = "tvos") { 3 } else if cfg ! (target_os = "watchos") { 4 } else if cfg ! (target_os = "visionos") { 11 } else { 0 } ; debug_assert_eq ! (platform , BASE_TARGET_PLATFORM , "invalid platform provided to __isPlatformVersionAtLeast" ,) ; (version <= current_version ()) as i32 } #[doc = " Old entry point for availability. Used when compiling with older Clang versions."] #[rustc_std_internal_symbol] #[linkage = "weak"] pub (super) extern "C" fn __isOSVersionAtLeast (major : i32 , minor : i32 , subminor : i32) -> i32 { let version = pack_i32_os_version (major , minor , subminor) ; (version <= current_version ()) as i32 }